validator:
function validate(input) {
  const [{ books = [] }] = input;
  const ids = new Set();
  for (const [id, , , , rating] of books) {
    if (id === null) return 'Every book needs a book_id.';
    if (ids.has(id)) return `book_id ${id} appears twice.`;
    ids.add(id);
    if (rating !== null && (Math.abs(rating) >= 100 || Math.abs(rating * 10 - Math.round(rating * 10)) > 1e-9)) return `Book ${id}: rating must fit DECIMAL(3, 1).`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const titles = ['Dune', 'Emma', 'Ulysses', 'Beloved', 'Hamlet', 'Animal Farm', 'Middlemarch', 'Lord of the Flies'];
  const authors = ['Frank Herbert', 'Jane Austen', 'James Joyce', 'Toni Morrison', 'George Orwell', 'Harper Lee'];
  const ratings = [null, null, 0, 2.5, 3.9, 4.2, 4.5, 5];
  const books = [];
  const count = size === 'small' ? pick(9) : 2000;
  // Distinct ids drawn from a wider range and visited in a scrambled order.
  const ids = Array.from({ length: size === 'small' ? 20 : 3000 }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [ids[i], ids[j]] = [ids[j], ids[i]];
  }
  for (let k = 0; k < count; k++) {
    books.push([ids[k], titles[pick(titles.length)], authors[pick(authors.length)], 1800 + pick(225), ratings[pick(ratings.length)]]);
  }
  return [{ books }];
}
